+  async dispatch(ctx) {
+    ctx = ctx ?? {}
+    ctx.params = ctx.params ?? {}
+    ctx.state = ctx.state ?? {}
+
+    const match = this.match(ctx.method, new URL(ctx.path ?? ctx.url ?? '/', 'http://localhost').pathname)
+
+    // compose middleware + handler
+    let idx = -1
+    const that = this
+
+    async function runner(i) {
+      if (i <= idx) throw new Error('next() called multiple times')
+      idx = i
+      if (i < that.middleware.length) {
+        const mw = that.middleware[i]
+        return await mw(ctx, () => runner(i + 1))
+      }
+      // after middleware, call matched handler or return 404
+      try {
+        if (!match) return { status: 404, body: { error: 'Not found' } }
+        // set params from match
+        ctx.params = match.params
+        return await match.handler(ctx)
+      } catch (err) {
+        if (typeof err?.status === 'number') return { status: err.status, body: { error: err.message } }
+        return { status: 500, body: { error: 'Internal error' } }
+      }
+    }
+
