--- a/src/server.js
+++ b/src/server.js
@@ -11,6 +11,44 @@ import { formatCurrency } from './format.js'
 export function createApp(inventory = Inventory.fromFile()) {
   const router = new Router()

+  // request id generator
+  let reqCounter = 0
+
+  // middleware: add x-request-id to every response
+  router.use(async (ctx, next) => {
+    const id = `${Date.now().toString(36)}-${++reqCounter}`
+    try {
+      const res = await next()
+      // ensure headers object
+      res.headers = { ...(res.headers ?? {}), 'x-request-id': id }
+      return res
+    } catch (err) {
+      // convert thrown errors into response objects per spec
+      if (typeof err?.status === 'number') {
+        const out = { status: err.status, body: { error: err.message } }
+        out.headers = { ...(out.headers ?? {}), 'x-request-id': id }
+        return out
+      }
+      const out = { status: 500, body: { error: 'Internal error' } }
+      out.headers = { ...(out.headers ?? {}), 'x-request-id': id }
+      return out
+    }
+  })
+
+  // API key auth middleware
+  router.use(async (ctx, next) => {
+    // read keys on every request
+    const raw = process.env.API_KEYS
+    if (!raw) return next()
+    const keys = raw.split(',').map((s) => s.trim()).filter(Boolean)
+    const method = ctx.method ?? 'GET'
+    if (['POST', 'PUT', 'PATCH', 'DELETE'].includes(method)) {
+      const provided = (ctx.headers && (ctx.headers['x-api-key'] ?? ctx.headers['X-API-Key'] ?? ctx.headers['x-api-key'])) || ''
+      if (!keys.includes(provided)) return { status: 401, body: { error: 'Unauthorized' } }
+    }
+    return next()
+  })
+
   router.get('/health', () => ({ status: 200, body: { status: 'ok' } }))

